; ----------------------------------------------------------------------------------------------------------
; NMI - the non-maskable interrupt, generated by the timer of CIA 2
;
; On the C64 the /IRQ output of CIA 2 is wired to the CPU's /NMI line (together with the RESTORE key).
; Unlike IRQ, NMI cannot be disabled with SEI and triggers on the falling edge of the line: once served, the
; next one comes only after the line has gone back high, that is after reading the CIA's interrupt register
; ($DD0D), which clears the flags and releases it.
;
; When an NMI arrives the KERNAL executes SEI and jumps to the address in vector $0318 WITHOUT saving the
; registers: the handler must save them and end with RTI. Here timer A of CIA 2 generates an NMI every
; 50000 cycles (about 20 times per second) and every 10 NMIs the border changes color. BASIC stays usable.
; ----------------------------------------------------------------------------------------------------------

NMI_VECTOR  = $0318         ; KERNAL NMI vector
CIA2_TA_LO  = $DD04         ; timer A: start value (latch), low byte
CIA2_TA_HI  = $DD05         ;          high byte
CIA2_ICR    = $DD0D         ; interrupts: written, enables (bit 7 = 1) or disables them; read, clears them
CIA2_CRA    = $DD0E         ; timer A control
BORDER      = $D020
COUNT       = $FB
PERIOD      = 10            ; NMIs between two color changes
TICKS       = 50000         ; cycles between two NMIs

            * = $0801
            .basic

            LDA #<nmi
            STA NMI_VECTOR
            LDA #>nmi
            STA NMI_VECTOR+1
            LDA #PERIOD
            STA COUNT
            LDA #<TICKS
            STA CIA2_TA_LO
            LDA #>TICKS
            STA CIA2_TA_HI
            LDA #%10000001              ; bit 7 = enable, bit 0 = timer A
            STA CIA2_ICR
            LDA #%00010001              ; bit 4 = load the latch, bit 0 = start; bit 3 = 0: continuous
            STA CIA2_CRA
            RTS

nmi:        PHA                         ; the KERNAL saved nothing: we save A
            LDA CIA2_ICR                ; acknowledge: clears the flags and releases the /NMI line
            DEC COUNT
            BNE done
            LDA #PERIOD
            STA COUNT
            INC BORDER                  ; next color (the VIC-II uses only the 4 low bits)
done:       PLA
            RTI                         ; also restores the status (and the I flag) from before the NMI
